/* ============================================
   Volta Studio — Corporate Website Styles
   ============================================ */

/* CSS Variables */
:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --accent-terracotta: #C47A5A;
  --accent-sage: #8FA68E;
  --accent-sand: #D4B996;
  --border: rgba(26, 26, 26, 0.12);
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --transition: 0.3s ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  color: var(--text);
  background-color: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
}

h2 {
  font-size: clamp(1.75rem, 4vw, 3rem);
}

h3 {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
}

p {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ============================================
   Header & Navigation
   ============================================ */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  padding: 1.5rem 3rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(245, 242, 237, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}

.site-header.scrolled {
  border-bottom-color: var(--border);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.nav-desktop {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}

.nav-desktop a {
  font-size: 0.9375rem;
  font-weight: 500;
  position: relative;
  padding-bottom: 0.25rem;
  transition: opacity var(--transition);
}

.nav-desktop a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width var(--transition);
}

.nav-desktop a:hover::after,
.nav-desktop a.active::after {
  width: 100%;
}

.nav-desktop a:hover {
  opacity: 0.7;
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  z-index: 1100;
  background: none;
  border: none;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  margin: 3px 0;
  transition: all 0.3s ease;
  border-radius: 1px;
}

.menu-toggle.active span:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}

/* Mobile Overlay Menu */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 1050;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu ul {
  list-style: none;
  text-align: center;
}

.mobile-menu li {
  margin: 1.5rem 0;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 700;
  line-height: 1.2;
  transition: opacity var(--transition);
}

.mobile-menu a:hover {
  opacity: 0.5;
}

/* ============================================
   Main Layout Helpers
   ============================================ */

main {
  padding-top: 80px;
}

.section {
  padding: 6rem 3rem;
  max-width: 1400px;
  margin: 0 auto;
}

.section-narrow {
  max-width: 720px;
  margin: 0 auto;
  padding: 6rem 2rem;
}

/* ============================================
   Home — Hero
   ============================================ */

.hero {
  padding: 8rem 3rem 4rem;
  max-width: 1400px;
  margin: 0 auto;
}

.hero-title {
  max-width: 900px;
  font-size: clamp(2.25rem, 5.5vw, 4rem);
  line-height: 1.15;
  letter-spacing: -0.025em;
}

/* ============================================
   Home — Media Showcase (Triptych)
   ============================================ */

.media-showcase {
  width: 100%;
  padding: 2rem 0 4rem;
}

.triptych {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  padding: 0 3rem;
  max-width: 1400px;
  margin: 0 auto;
}

.triptych-item {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
  overflow: hidden;
}

.triptych-item.terracotta {
  background: var(--accent-terracotta);
}

.triptych-item.sage {
  background: var(--accent-sage);
}

.triptych-item.sand {
  background: var(--accent-sand);
}

/* ============================================
   Client Marquee
   ============================================ */

.marquee-section {
  padding: 4rem 0;
  overflow: hidden;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  padding: 0.75rem 0;
  will-change: transform;
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: 3rem;
  padding-right: 3rem;
  animation: marquee-left 30s linear infinite;
}

.marquee-row.reverse .marquee-track {
  animation: marquee-right 30s linear infinite;
}

.marquee-track span {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 600;
  color: var(--text);
  opacity: 0.35;
  letter-spacing: -0.01em;
}

.marquee-dot {
  width: 6px;
  height: 6px;
  background: var(--text);
  opacity: 0.25;
  border-radius: 50%;
  flex-shrink: 0;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ============================================
   About Section
   ============================================ */

.about-section {
  padding: 6rem 3rem;
  max-width: 900px;
  margin: 0 auto;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.about-text {
  font-size: clamp(1.0625rem, 1.8vw, 1.25rem);
  line-height: 1.75;
  color: var(--text-muted);
}

.about-text p + p {
  margin-top: 1.5rem;
}

/* ============================================
   Neweno — Founder Letter
   ============================================ */

.letter-page {
  padding-top: 120px;
  padding-bottom: 6rem;
}

.letter-header {
  text-align: center;
  margin-bottom: 4rem;
}

.letter-header h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 0.5rem;
}

.letter-header .subhead {
  font-size: 1rem;
  color: var(--text-muted);
  font-style: italic;
  font-family: var(--font-serif);
}

.letter-body {
  max-width: 680px;
  margin: 0 auto;
  padding: 0 2rem;
}

.letter-body p {
  font-size: clamp(1.0625rem, 1.6vw, 1.1875rem);
  line-height: 1.85;
  color: var(--text-muted);
  margin-bottom: 1.75rem;
}

.letter-body p:first-of-type::first-letter {
  font-family: var(--font-serif);
  font-size: 4.5rem;
  float: left;
  line-height: 0.8;
  padding-right: 0.75rem;
  padding-top: 0.25rem;
  font-weight: 700;
  color: var(--text);
}

.letter-signature {
  margin-top: 3rem;
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-style: italic;
  color: var(--text);
}

/* ============================================
   Services Page
   ============================================ */

.services-hero {
  padding: 8rem 3rem 3rem;
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.philosophy-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  margin-bottom: 2.5rem;
}

.philosophy-body {
  font-size: clamp(1.0625rem, 1.8vw, 1.25rem);
  line-height: 1.75;
  color: var(--text-muted);
  max-width: 700px;
  margin: 0 auto;
}

.divider {
  width: 60px;
  height: 1px;
  background: var(--border);
  margin: 5rem auto;
}

.services-details {
  max-width: 900px;
  margin: 0 auto;
  padding: 0 3rem 6rem;
}

.services-question {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  margin-bottom: 3rem;
  text-align: center;
}

.service-item {
  margin-bottom: 3.5rem;
}

.service-item h3 {
  font-size: clamp(1.25rem, 2.5vw, 1.5rem);
  margin-bottom: 0.75rem;
  color: var(--text);
}

.service-item p {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ============================================
   Clients Page
   ============================================ */

.clients-page {
  padding: 8rem 3rem 6rem;
  max-width: 1200px;
  margin: 0 auto;
}

.clients-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  margin-bottom: 4rem;
  text-align: center;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2.5rem;
}

.client-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
  color: var(--text);
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--text-muted);
}

/* ============================================
   Contact Page
   ============================================ */

.contact-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 8rem 2rem 4rem;
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 15vw, 12rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.contact-links a {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 500;
  transition: opacity var(--transition);
}

.contact-links a:hover {
  opacity: 0.5;
}

/* ============================================
   Footer
   ============================================ */

.site-footer {
  padding: 3rem;
  text-align: center;
  border-top: 1px solid var(--border);
}

.site-footer p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 768px) {
  .site-header {
    padding: 1.25rem 1.5rem;
  }

  .nav-desktop {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .hero {
    padding: 6rem 1.5rem 2rem;
  }

  .triptych {
    grid-template-columns: 1fr;
    padding: 0 1.5rem;
  }

  .section,
  .about-section,
  .services-details,
  .clients-page {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .letter-body {
    padding: 0 1.5rem;
  }

  .contact-title {
    font-size: clamp(3.5rem, 18vw, 7rem);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile menu toggle
  const menuToggle = document.querySelector('.menu-toggle');
  const mobileMenu = document.querySelector('.mobile-menu');

  if (menuToggle && mobileMenu) {
    menuToggle.addEventListener('click', () => {
      menuToggle.classList.toggle('active');
      mobileMenu.classList.toggle('open');
      document.body.style.overflow = mobileMenu.classList.contains('open') ? 'hidden' : '';
    });

    // Close menu when a link is clicked
    mobileMenu.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        menuToggle.classList.remove('active');
        mobileMenu.classList.remove('open');
        document.body.style.overflow = '';
      });
    });
  }

  // Header scroll state
  const header = document.querySelector('.site-header');
  if (header) {
    window.addEventListener('scroll', () => {
      if (window.scrollY > 20) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    });
  }
});
